The bulk update and delete operations throw errors indicating they are not implemented, but this breaking change is not mentioned in the PR description or README migration guide. Users relying on these operations will experience runtime failures.
```suggestion
        // Fallback implementation: iterate and call single-record update
        const results: T[] = [];
        for (const item of data) {
          const record: any = item as any;
          const id = record?.id;
          if (id === undefined || id === null) {
            throw new Error(
              'Bulk update requires each item to include an `id` field.'
            );
          }
          // Do not send id as part of the update payload
          const { id: _omitId, ...updateData } = record;
          const updated = await this.client.update<T>(resource, id, updateData);
          if (updated !== undefined && updated !== null) {
            results.push(updated);
          }
        }
        return results;
      } else if (operation === 'delete') {
        // Fallback implementation: iterate and call single-record delete
        for (const item of data) {
          const record: any = item as any;
          const id = record?.id ?? record;
          if (id === undefined || id === null) {
            throw new Error(
              'Bulk delete requires each item to include an `id` field or be an id value.'
            );
          }
          await this.client.delete(resource, id);
        }
        // For delete operations, we return an empty array by convention
        return [];
```

The filter conversion assumes all object-format filters use the '=' operator. This is incorrect for MongoDB-like syntax where `params.$filter` could be `{ age: { $gte: 18 } }`. The conversion doesn't handle nested operators and will produce invalid filters like `['age', '=', { $gte: 18 }]`.
```suggestion
        // Convert object format (including Mongo-like operator objects) to FilterExpression format
        const filterEntries = Object.entries(params.$filter);
        const filters: any[] = [];

        const operatorMap: Record<string, string> = {
          $eq: '=',
          $ne: '!=',
          $gt: '>',
          $gte: '>=',
          $lt: '<',
          $lte: '<=',
          $in: 'in',
          $nin: 'not-in',
        };

        for (const [key, value] of filterEntries) {
          const isPlainObject =
            value !== null &&
            typeof value === 'object' &&
            !Array.isArray(value);

          if (isPlainObject) {
            const opEntries = Object.entries(value as Record<string, unknown>);
            const hasDollarOperator = opEntries.some(([op]) => op.startsWith('$'));

            if (hasDollarOperator) {
              for (const [rawOp, opValue] of opEntries) {
                const mappedOp =
                  operatorMap[rawOp as keyof typeof operatorMap] ??
                  rawOp.replace(/^\$/, '');
                filters.push([key, mappedOp, opValue]);
              }
              continue;
            }
          }

          // Fallback: treat as simple equality
          filters.push([key, '=', value]);
        }

        objectqlParams.filter = filters as FilterExpression;
```
